# Task Dashboard — React + TypeScript

Complete, self-contained implementation. All components included below.

## 1. Types & Data

```tsx
// types.ts
export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  priority: "low" | "medium" | "high";
  projectId: string;
  assignee: string;
  dueDate: string; // ISO
}

export interface Project {
  id: string;
  name: string;
  color: string;
}

export const STATUS_LABELS: Record<TaskStatus, string> = {
  todo: "To Do",
  "in-progress": "In Progress",
  done: "Done",
};

export const PRIORITY_LABELS = {
  low: "Low",
  medium: "Medium",
  high: "High",
} as const;
```

